// Maps entityType -> how to find/extract its scoping id from the query string,
// and how to build the composite path once extracted.
const EXCEPTION_ENTITY_CONFIG = {
    pay_component_log:       { queryKey: 'PaySlipId',   build: v => `pay_component_log/pay_slip/${v}` },
    pay_schedule:            { queryKey: 'Id',          build: v => `pay_schedule/${v}` },
    position_pay_component:  { queryKey: 'PositionId',  build: v => `position_pay_component/position/${v}` },
    user:                    { queryKey: 'Id',          build: v => `user/${v}` },
    user_role:               { queryKey: 'UserId',      build: v => `user_role/user/${v}` },
    worker:                  { queryKey: 'Id',          build: v => `worker/${v}` }
};

const DEFAULT_QUERY_KEY = 'WorkerId'; // default {entityType}/worker/{id} shape

const {
    entityType,
    customEntityKey,
    columnDefs,
    page = 1,
    limit = 25,
    query = "",
    hydrateOnLoad = false,
    resetUiState = true,
    touchLoadingStates = true,
    reloadColumns = false
} = options;

const exceptionConfig = EXCEPTION_ENTITY_CONFIG[entityType];
const queryKey = exceptionConfig?.queryKey ?? DEFAULT_QUERY_KEY;

const { value: idValue, remainingQuery } = this.extractIdFromQuery(query, queryKey);

if (!idValue) {
    console.error(`[WorkerGridController] Missing required '${queryKey}' filter in query for entityType: ${entityType}`);
    context.utils.toast(`Missing required '${queryKey}' filter for ${entityType}`, "ERROR");
    return;
}

const builtEntityPath = exceptionConfig
    ? exceptionConfig.build(idValue)
    : `${entityType}/worker/${idValue}`;

const store = context.tabStore[entityType];
if (!store) return;

// Create unique request ID for each call
// Attach it to each store so each tab tracks its own requests
store.currentRequestId = (store.currentRequestId ?? 0) + 1;
const currentRequestId = store.currentRequestId;

// Prepare the UI
if (touchLoadingStates) context.uiState.isLoadingTable = true;
if (resetUiState) this.resetState(context.uiState);

try {
    const result = await context.payrollApiService.get({
        entity: builtEntityPath,
        page,
        limit,
        query: remainingQuery,
        customEntityKey
    });

    // Abort if newer request was triggered
    if (store.currentRequestId !== currentRequestId) return;

    const dataKey = customEntityKey || 'entities';
    const rawEntities = result[dataKey] ?? result.entities ?? result[entityType] ?? [];

    // Format API response for util processing
    const entitiesArray = Array.isArray(rawEntities)
        ? rawEntities
        : (rawEntities ? [rawEntities] : []);

    // Normalize Data
    const booleanKeys = context.utils.extractBooleanKeys(columnDefs);
    const cleanEntities = context.utils.normalizeBooleans(entitiesArray, booleanKeys);

    let finalData = cleanEntities;

    if (context.referenceDataService && context.referenceDataService.hydrateEntity && hydrateOnLoad) {
        finalData = await Promise.all(
            cleanEntities.map(entity => context.referenceDataService.hydrateEntity(entity))
        );

        if (store.currentRequestId !== currentRequestId) return;
    }

    // Update Tab Store
    store.data = finalData;
    store.currentPage = result.metadata?.currentPage ?? page;
    store.totalFiltered = result.metadata?.totalFiltered ?? entitiesArray.length;
    store.totalCount = result.metadata?.totalCount ?? entitiesArray.length;
    store.hasNextPage = result.metadata?.hasNextPage ?? (entitiesArray.length === limit);
    store.pageCount = (result.metadata?.pageCount && result.metadata?.pageCount > 0)
        ? result.metadata.pageCount
        : (store.hasNextPage ? page + 1 : page);

    // Lazy-load Column Definitions
    if (!store.columns || store.columns.length === 0 || reloadColumns) {
        store.columns = context.utils.generateColumnDefinitions(columnDefs);
    }

    return finalData;
} catch (error) {
    if (store.currentRequestId === currentRequestId) {
        // Payroll api service get does not return the 404 error, used error message instead
        const isNotFoundError = entityType === 'user' && /not found/i.test(error?.message ?? '');

        if (isNotFoundError) {
            context.utils.toast(`User not Found`, "ERROR");
            context.$state.go("people_management");
        } else {
            console.error(`[WorkerGridController] Error loading ${entityType}`, error);
            context.utils.toast(`Failed to load ${entityType}`, "ERROR");
        }

        throw error;
    }
} finally {
    if (store.currentRequestId === currentRequestId && touchLoadingStates) {
        context.uiState.isLoadingTable = false;
    }
}

uiState.selectedEntity = null;
uiState.selectedEntityName = "";
uiState.detailsList = [];
if (Object.hasOwn(uiState, 'isFormOpen')) {
    uiState.isFormOpen = false;
}

if (Object.hasOwn(uiState, 'isAdding')) {
    uiState.isAdding = false;
}

if (Object.hasOwn(uiState, 'isEditing')) {
    uiState.isEditing = false;
}

if (Object.hasOwn(uiState, 'isCreatingNewEntity')) {
    uiState.isCreatingNewEntity = false;
}

if (Object.hasOwn(uiState, 'isEditingExistingEntity')) {
    uiState.isEditingExistingEntity = false;
}

/**
 * Extracts a filter value like "WorkerId_eq=123" or "WorkerId=123" from a
 * query string, and returns both the extracted value and the remaining
 * query string with that filter removed (so it isn't sent twice).
 */
const pattern = new RegExp(`(?:^|&)${queryKey}(?:_eq)?=([^&]+)`);
const match = query.match(pattern);
if (!match) return { value: null, remainingQuery: query };

const value = decodeURIComponent(match[1]);
const remainingQuery = query.replace(pattern, '').replace(/^&/, '');
return { value, remainingQuery };
